{
  "name": "Document Methodology Extractor",
  "description": "An application to upload a document image, extract its key ideas, and provide a detailed breakdown of its methodology using the Gemini API."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import { FileUpload } from './components/FileUpload';
import { ResultsDisplay } from './components/ResultsDisplay';
import { Spinner } from './components/Spinner';
import { extractKeyIdeasAndMethodology } from './services/geminiService';

const App: React.FC = () => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [analysisResult, setAnalysisResult] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string>('');

  const handleFileChange = useCallback((file: File | null) => {
    setImageFile(file);
    setAnalysisResult('');
    setError('');
  }, []);

  const fileToGenerativePart = async (file: File) => {
    const base64EncodedDataPromise = new Promise<string>((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          resolve(reader.result.split(',')[1]);
        } else {
          resolve('');
        }
      };
      reader.readAsDataURL(file);
    });

    const base64EncodedData = await base64EncodedDataPromise;
    return {
      inlineData: {
        data: base64EncodedData,
        mimeType: file.type,
      },
    };
  };

  const handleAnalysis = async () => {
    if (!imageFile) {
      setError('Please upload an image file first.');
      return;
    }

    setIsLoading(true);
    setError('');
    setAnalysisResult('');

    try {
      const imagePart = await fileToGenerativePart(imageFile);
      const result = await extractKeyIdeasAndMethodology(imagePart);
      if(result) {
        setAnalysisResult(result);
      } else {
        setError('Failed to get a valid response from the model.');
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An unknown error occurred.';
      setError(`Analysis failed: ${errorMessage}`);
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 font-sans">
      <header className="bg-white dark:bg-gray-800 shadow-md">
        <div className="container mx-auto px-4 py-4 sm:px-6 lg:px-8 flex items-center justify-between">
          <h1 className="text-2xl sm:text-3xl font-bold text-gray-800 dark:text-white">
            Document Methodology Extractor
          </h1>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="h-8 w-8 text-blue-500"
            viewBox="0 0 20 20"
            fill="currentColor"
          >
            <path
              fillRule="evenodd"
              d="M4 4a2 2 0 012-2h8a2 2 0 012 2v12a1 1 0 11-2 0V4H6a1 1 0 110-2zm4 7a1 1 0 011-1h2a1 1 0 110 2H9a1 1 0 01-1-1zm0 4a1 1 0 100 2h2a1 1 0 100-2H8z"
              clipRule="evenodd"
            />
          </svg>
        </div>
      </header>

      <main className="container mx-auto p-4 sm:p-6 lg:p-8">
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-lg p-6 max-w-4xl mx-auto">
          <div className="mb-6">
            <h2 className="text-xl font-semibold mb-2 text-gray-700 dark:text-gray-200">Upload Document Image</h2>
            <p className="text-gray-600 dark:text-gray-400 mb-4">
              Select an image of a document page. The model will analyze it to extract key ideas and methodologies.
            </p>
            <FileUpload onFileChange={handleFileChange} />
          </div>

          <div className="flex justify-center mb-6">
            <button
              onClick={handleAnalysis}
              disabled={!imageFile || isLoading}
              className="px-8 py-3 bg-blue-600 text-white font-semibold rounded-lg shadow-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-75 disabled:bg-gray-400 disabled:cursor-not-allowed transition-all duration-300 ease-in-out transform hover:scale-105 disabled:transform-none"
            >
              {isLoading ? 'Analyzing...' : 'Extract Insights'}
            </button>
          </div>

          {isLoading && <Spinner />}

          {error && (
            <div className="mt-6 p-4 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-600 text-red-700 dark:text-red-200 rounded-lg">
              <p className="font-bold">Error</p>
              <p>{error}</p>
            </div>
          )}

          {analysisResult && !isLoading && (
            <ResultsDisplay result={analysisResult} />
          )}

          {!analysisResult && !isLoading && !error && (
            <div className="text-center py-10 px-6 bg-gray-100 dark:bg-gray-700 rounded-lg">
              <svg xmlns="http://www.w3.org/2000/svg" className="mx-auto h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              <h3 className="mt-2 text-lg font-medium text-gray-900 dark:text-gray-100">Analysis Results Will Appear Here</h3>
              <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">Upload an image and click "Extract Insights" to begin.</p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef } from 'react';

interface FileUploadProps {
  onFileChange: (file: File | null) => void;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileChange }) => {
  const [fileName, setFileName] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0] || null;
    setFileName(file ? file.name : '');
    onFileChange(file);
  }, [onFileChange]);

  const handleDragOver = useCallback((event: React.DragEvent<HTMLLabelElement>) => {
    event.preventDefault();
  }, []);

  const handleDrop = useCallback((event: React.DragEvent<HTMLLabelElement>) => {
    event.preventDefault();
    const file = event.dataTransfer.files?.[0] || null;
    if (file && file.type.startsWith('image/')) {
        setFileName(file.name);
        onFileChange(file);
        if (fileInputRef.current) {
            fileInputRef.current.files = event.dataTransfer.files;
        }
    }
  }, [onFileChange]);

  return (
    <div>
      <label 
        htmlFor="file-upload" 
        className="relative cursor-pointer bg-white dark:bg-gray-700 rounded-md font-medium text-blue-600 dark:text-blue-400 hover:text-blue-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-blue-500 border-2 border-dashed border-gray-300 dark:border-gray-600 p-6 flex flex-col items-center justify-center transition-colors duration-300"
        onDragOver={handleDragOver}
        onDrop={handleDrop}
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
        </svg>
        <span className="mt-2 block text-sm text-gray-900 dark:text-gray-100">
            <span className="font-semibold">Click to upload</span> or drag and drop
        </span>
        <p className="text-xs text-gray-500 dark:text-gray-400">PNG, JPG, WEBP up to 10MB</p>
        <input
            id="file-upload"
            name="file-upload"
            type="file"
            className="sr-only"
            accept="image/*"
            onChange={handleFileChange}
            ref={fileInputRef}
        />
      </label>
      {fileName && (
        <div className="mt-4 text-sm text-gray-700 dark:text-gray-300">
          <span className="font-semibold">Selected file:</span> {fileName}
        </div>
      )}
    </div>
  );
};

import React from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

interface ResultsDisplayProps {
  result: string;
}

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ result }) => {
  return (
    <div className="mt-6 bg-gray-50 dark:bg-gray-700/50 p-6 rounded-lg shadow-inner">
      <h3 className="text-xl font-semibold mb-4 text-gray-800 dark:text-gray-100">Analysis Results</h3>
      <div className="prose prose-blue dark:prose-invert max-w-none">
        <ReactMarkdown remarkPlugins={[remarkGfm]}>
            {result}
        </ReactMarkdown>
      </div>
    </div>
  );
};

import React from 'react';

export const Spinner: React.FC = () => {
  return (
    <div className="flex justify-center items-center my-6">
      <div className="animate-spin rounded-full h-12 w-12 border-t-4 border-b-4 border-blue-500"></div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

const model = 'gemini-3-flash-preview';

interface GenerativePart {
  inlineData: {
    data: string;
    mimeType: string;
  };
}

export const extractKeyIdeasAndMethodology = async (imagePart: GenerativePart): Promise<string | null> => {
  try {
    const prompt = `
      Analyze this image of a research paper. 
      Your task is to extract two main sections: Key Ideas and Methodology.

      1.  **Key Ideas:** Summarize the main contributions, findings, and core concepts presented in the paper. This should be a high-level overview of what the paper is about and what it achieves.
      2.  **Methodology:** Provide a detailed breakdown of the proposed method or workflow described in the paper. Explain the steps, components, architecture, and processes involved. Be as specific as the text allows.

      Structure your entire response in Markdown format. Use headings, subheadings, bullet points, and bold text for clarity and readability.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: { parts: [{ text: prompt }, imagePart] },
    });

    return response.text ?? null;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Failed to communicate with the Gemini API.");
  }
};
